), n as (
  select regexp_replace(upper(ffr_no), '\s', '', 'g') as fk, upper(btrim(ucn)) as uk, ts from s
), f as (
  select regexp_replace(upper(ffr_no), '\s', '', 'g') as fk, upper(btrim(ucn)) as uk from public.field_failure_reports
), m as (
  select n.*, exists (select 1 from f where f.fk = n.fk and f.uk = n.uk) as hit,
         ts = max(ts) over (partition by fk) as latest
    from n
), per as (
  select fk, bool_or(hit) as any_hit, bool_or(hit and latest) as latest_hit,
         (select count(*) from f where f.fk = m.fk) as reg_rows,
         count(distinct uk) as sheet_ucns
    from m group by fk
)
select 1 as k, 'sheet rows' as what, count(*)::text as n from m
union all select 2, 'rows matching FFR No + UCN', count(*) filter (where hit)::text from m
union all select 3, 'FFR numbers in the sheet', (select count(*) from per)::text
union all select 4, 'FFRs with at least one row matching on UCN', (select count(*) filter (where any_hit) from per)::text
union all select 5, 'FFRs whose LATEST row matches on UCN', (select count(*) filter (where latest_hit) from per)::text
union all select 6, 'FFRs with NO row matching on UCN', (select count(*) filter (where not any_hit) from per)::text
union all select 7, 'FFRs with one UCN in the sheet', (select count(*) filter (where sheet_ucns = 1) from per)::text
union all select 8, 'FFRs with one UCN in the sheet that does not match', (select count(*) filter (where sheet_ucns = 1 and not any_hit) from per)::text
union all select 9, 'register FFR numbers with more than one row', (select count(*) from (select fk from f group by fk having count(*) > 1) z)::text
order by 1;
